// scripts/botFirebase.ts
var config = JSON.parse(readFileSync(new URL("../firebase-applet-config.json", import.meta.url), "utf8"));
var SITIO = `${SITIO_URL}/`;
async function iniciarSesionBot() {
  const clave = process.env.UNINEXO_BOT_PASSWORD;
  if (!clave) throw new Error("Falta UNINEXO_BOT_PASSWORD en el .env del bot.");
  const extra = {};
  const debug = process.env.UNINEXO_BOT_APPCHECK_DEBUG;
  if (debug) {
    const r2 = await fetch(`https://firebaseappcheck.googleapis.com/v1/projects/${config.projectId}/apps/${config.appId}:exchangeDebugToken?key=${config.apiKey}`, {
      method: "POST",
      headers: { "Content-Type": "application/json", Referer: SITIO },
      body: JSON.stringify({ debugToken: debug })
    });
    const j2 = await r2.json();
    if (!r2.ok || !j2.token) throw new Error(`App Check no acept\xF3 el token del bot (${j2?.error?.message || r2.status}). \xBFSigue registrado en la consola?`);
    extra["X-Firebase-AppCheck"] = j2.token;
  }
  const r = await fetch(`https://identitytoolkit.googleapis.com/v1/accounts:signInWithPassword?key=${config.apiKey}`, {
    method: "POST",
    headers: { "Content-Type": "application/json", Referer: SITIO, ...extra },
    body: JSON.stringify({ email: process.env.UNINEXO_BOT_EMAIL || BOT_EMPLEOS_CORREO, password: clave, returnSecureToken: true })
  });
  const j = await r.json();
  if (!r.ok) throw new Error(`No pude iniciar sesi\xF3n con la cuenta del bot (${j?.error?.message || r.status}).`);
  const token = j.idToken;
  const base = `projects/${config.projectId}/databases/(default)/documents`;
  const commit = async (writes) => {
    const res = await fetch(`https://firestore.googleapis.com/v1/${base}:commit`, {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}`, ...extra },
      body: JSON.stringify({ writes })
    });
    if (!res.ok) {
      const e = await res.json().catch(() => ({}));
      throw new Error(e?.error?.status || `HTTP ${res.status}`);
    }
  };
  return {
    uid: j.localId,
    escribir: (ruta, datos, horaServidor = []) => commit([{
      update: { name: `${base}/${ruta}`, fields: aFirestore(datos) },
      ...horaServidor.length ? { updateTransforms: horaServidor.map((fieldPath) => ({ fieldPath, setToServerValue: "REQUEST_TIME" })) } : {}
    }]),
    crear: async (coleccion, docs) => {
      const res = await fetch(`https://firestore.googleapis.com/v1/${base}:commit`, {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}`, ...extra },
        // currentDocument.exists=false: solo CREA (si ya existe, no la pisa)
        body: JSON.stringify({ writes: docs.map((d) => ({ update: { name: `${base}/${coleccion}/${d.id}`, fields: aFirestore(d) }, currentDocument: { exists: false } })) })
      });
      if (!res.ok) {
        const e = await res.json().catch(() => ({}));
        throw new Error(e?.error?.status || `HTTP ${res.status}`);
      }
    }
  };
}

