// src/utils/beca18Config.ts
var BECA18_DOC = "preu_config/beca18";
var MAX_FECHAS_BECA18 = 8;
var FECHA = /^20\d\d-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/;
var CONVOCATORIA = /^Convocatoria 20\d\d$/;
function validarCronogramaBeca18(x) {
  if (!x || typeof x !== "object") return null;
  const d = x;
  if (typeof d.convocatoria !== "string" || !CONVOCATORIA.test(d.convocatoria)) return null;
  if (typeof d.revisado !== "string" || !FECHA.test(d.revisado)) return null;
  if (!Array.isArray(d.cronograma) || d.cronograma.length < 1 || d.cronograma.length > MAX_FECHAS_BECA18) return null;
  const cronograma = [];
  for (const f of d.cronograma) {
    if (!f || typeof f !== "object") return null;
    const { que, desde, hasta } = f;
    if (typeof que !== "string" || que.trim().length < 3 || que.length > 140) return null;
    if (typeof desde !== "string" || typeof hasta !== "string" || !FECHA.test(desde) || !FECHA.test(hasta) || hasta < desde) return null;
    cronograma.push({ que: que.trim(), desde, hasta });
  }
  return { convocatoria: d.convocatoria, cronograma, revisado: d.revisado };
}
var CRONOGRAMA_BECA18_CODIGO = { convocatoria: BECA18.convocatoria, cronograma: BECA18.cronograma, revisado: BECA18_REVISADO };
function documentoBeca18(c) {
  return { convocatoria: c.convocatoria, cronograma: c.cronograma, revisado: c.revisado, fuenteUrl: BECA18_URL };
}
var DURACION_BECA18_MS = 6 * 60 * 60 * 1e3;

// scripts/publicar-preu-bot.ts
var resumen = (x) => console.log("RESUMEN " + JSON.stringify(x));
(async () => {
  const archivo = process.argv[2];
  if (!archivo) throw new Error("Falta el archivo JSON con el cronograma.");
  const c = validarCronogramaBeca18(JSON.parse(readFileSync2(archivo, "utf8")));
  if (!c) return resumen({ estado: "invalida", motivo: "el cronograma no tiene la forma esperada (fechas AAAA-MM-DD, 1 a 8 filas, \xABConvocatoria 20XX\xBB)" });
  const sesion = await iniciarSesionBot();
  await sesion.escribir(BECA18_DOC, documentoBeca18(c), ["actualizado"]);
  resumen({ estado: "publicada", convocatoria: c.convocatoria, fechas: c.cronograma.length });
})().catch((e) => {
  resumen({ estado: "fallida", motivo: String(e.message).slice(0, 200) });
  process.exit(1);
});
